{
 "title": "System Language Discovery via Reg.Exe",
 "description": "Detects usage of Reg.Exe to query system language registry keys, indicative of discovery activity (T1614.001).",
 "tags": [
  "attack.discovery",
  "attack.t1614.001"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\\\reg.exe"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "query"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "Control Panel\\\\International",
      "Nls\\\\Language"
     ]
    }
   ]
  }
 ],
 "condition": "selection",
 "falsepositives": [
  "Legitimate administrative scripts querying locale settings."
 ],
 "level": "medium"
}

{
 "title": "User Shell Folders Registry Modification via reg.exe or PowerShell",
 "description": "Detects modifications to User Shell Folders registry values via reg.exe or PowerShell, which may indicate persistence attempts.",
 "tags": [
  "attack.persistence",
  "attack.privilege-escalation",
  "attack.defense-impairment",
  "attack.t1547.001",
  "attack.t1112"
 ],
 "logsource_category": "registry_set",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "TargetObject",
     "modifier": "contains",
     "values": [
      "\\User Shell Folders\\"
     ]
    },
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "reg.exe",
      "powershell.exe"
     ]
    },
    {
     "field": "Details",
     "modifier": "contains",
     "values": [
      ".exe",
      ".ps1",
      ".bat",
      ".cmd",
      ".vbs",
      ".js"
     ]
    }
   ]
  },
  {
   "name": "condition",
   "fields": []
  }
 ],
 "condition": "selection and not filter",
 "falsepositives": [
  "Legitimate software installing startup shortcuts via User Shell Folders using reg.exe or PowerShell"
 ],
 "level": "high"
}

{
 "title": "Cmd.exe Launched with Hidden Start Flags to Suspicious Targets",
 "description": "Detects cmd.exe executing the 'start' utility with /b (no window) or /min (minimized) flags where the target\n  is a known script extension or resides in suspicious temporary/public directories, indicative of stealth execution used\n  by Chaos, DarkSide, and Emotet.",
 "tags": [
  "attack.t1564.003",
  "attack.stealth"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_image",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\\\cmd.exe"
     ]
    }
   ]
  },
  {
   "name": "selection_flags",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      " start "
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "/b",
      "/min"
     ]
    }
   ]
  },
  {
   "name": "selection_target",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      ".bat",
      ".cmd",
      ".vbs",
      ".js",
      ".wsf",
      ".ps1",
      "\\\\Temp\\\\",
      "\\\\temp\\\\",
      "\\\\Public\\\\"
     ]
    }
   ]
  }
 ],
 "condition": "selection_image and selection_flags and selection_target",
 "falsepositives": [
  "Legitimate batch or script files launched via start /b or /min from trusted locations such as system directories or signed installers."
 ],
 "level": "high"
}

{
 "title": "Deletion of Volume Shadow Copies via WMI with PowerShell",
 "description": "Detects PowerShell usage of Get-WMIObject to delete Volume Shadow Copies (Win32_Shadowcopy) via the Delete method, indicative of ransomware impact behavior (T1490).",
 "tags": [
  "attack.t1490",
  "attack.impact"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_img",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\\\powershell.exe",
      "\\\\pwsh.exe"
     ]
    }
   ]
  },
  {
   "name": "selection_cmd",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "Get-WmiObject"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "Win32_Shadowcopy"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      ".Delete()"
     ]
    }
   ]
  }
 ],
 "condition": "selection_img and selection_cmd",
 "falsepositives": [
  "Legitimate administrative scripts that manage shadow copies."
 ],
 "level": "high"
}

{
 "title": "Deletion of Volume Shadow Copies via WMI with PowerShell",
 "description": "Detects PowerShell usage of Get-WMIObject to delete Volume Shadow Copies (Win32_Shadowcopy) via the Delete method, indicative of ransomware impact behavior (T1490).",
 "tags": [
  "attack.t1490",
  "attack.impact"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_img",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\\\powershell.exe",
      "\\\\pwsh.exe"
     ]
    }
   ]
  },
  {
   "name": "selection_cmd",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "Get-WmiObject",
      "Win32_Shadowcopy",
      ".Delete()"
     ]
    }
   ]
  },
  {
   "name": "selection_ps",
   "fields": [
    {
     "field": "EventID",
     "modifier": "exact",
