{
 "title": "Bitsadmin File Download",
 "description": "Detects usage of bitsadmin to download a file from a remote URL, indicative of adversarial file transfer.",
 "tags": [
  "attack.persistence",
  "attack.execution",
  "attack.stealth",
  "attack.t1197",
  "attack.s0190",
  "attack.t1036.003",
  "attack.command-and-control",
  "attack.t1105"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\\\bitsadmin.exe"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "re",
     "values": [
      "(?=.*/transfer)(?=.*https?://)"
     ]
    }
   ]
  },
  {
   "name": "filter",
   "fields": []
  }
 ],
 "condition": "selection",
 "falsepositives": [],
 "level": "high"
}

{
 "title": "Application Removed Via Wmic.EXE",
 "description": "Detects the removal or uninstallation of an application via \"Wmic.EXE\" as used in Atomic Red Team test T1047.010.",
 "tags": [
  "attack.execution",
  "attack.t1047"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\wmic.exe"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains|all",
     "values": [
      "product",
      "call",
      "uninstall"
     ]
    }
   ]
  },
  {
   "name": "filter",
   "fields": []
  }
 ],
 "condition": "selection and not filter",
 "falsepositives": [],
 "level": "high"
}
